import React from 'react';
import Hero from './Hero';
import Features from './Features';

export default function Home({ setCurrentPage }) {
  return (
    <div>
      <Hero setCurrentPage={setCurrentPage} />
      
      {/* Bright & Clean White Stats Section */}
      <div style={{ backgroundColor: '#4ebf1a', padding: '40px 20px', borderBottom: '1px solid #e2e8f0', boxShadow: '0 4px 12px rgba(0,0,0,0.02)' }}>
        <div style={{ maxWidth: '1100px', margin: '0 auto', display: 'flex', justifyContent: 'space-around', flexWrap: 'wrap', gap: '20px', textAlign: 'center' }}>
          <div style={{ padding: '10px 20px' }}>
            <h2 style={{ fontSize: '38px', margin: '0 0 4px 0', color: '#081c0f', fontWeight: '800' }}>9+</h2>
            <p style={{ margin: 0, fontSize: '15px', color: '#475569', fontWeight: '600' }}>Expert Subject Teachers</p>
          </div>
          <div style={{ padding: '10px 20px' }}>
            <h2 style={{ fontSize: '38px', margin: '0 0 4px 0', color: '#031409', fontWeight: '800' }}>Modern</h2>
            <p style={{ margin: 0, fontSize: '15px', color: '#475569', fontWeight: '600' }}>Physical & Digital Classrooms</p>
          </div>
          <div style={{ padding: '10px 20px' }}>
            <h2 style={{ fontSize: '38px', margin: '0 0 4px 0', color: '#15803d', fontWeight: '800' }}>100%</h2>
            <p style={{ margin: 0, fontSize: '15px', color: '#475569', fontWeight: '600' }}>Individual Student Attention</p>
          </div>
        </div>
      </div>

      <Features />
    </div>
  );
}
